<?php
require __DIR__ . '/config.php'; require_login();
$title = 'Dashboard';
$isAdmin = (($_SESSION['role'] ?? 'staff') === 'admin'); $uid=(int)$_SESSION['user_id'];
$total = (int)($isAdmin ? $pdo->query('SELECT COUNT(*) FROM documents')->fetchColumn() : (function() use($pdo,$uid){$s=$pdo->prepare('SELECT COUNT(*) FROM documents WHERE uploaded_by=?');$s->execute([$uid]);return $s->fetchColumn();})());
$today = (int)($isAdmin ? $pdo->query('SELECT COUNT(*) FROM documents WHERE DATE(created_at)=CURDATE()')->fetchColumn() : (function() use($pdo,$uid){$s=$pdo->prepare('SELECT COUNT(*) FROM documents WHERE DATE(created_at)=CURDATE() AND uploaded_by=?');$s->execute([$uid]);return $s->fetchColumn();})());
$week = (int)($isAdmin ? $pdo->query('SELECT COUNT(*) FROM documents WHERE created_at >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)')->fetchColumn() : (function() use($pdo,$uid){$s=$pdo->prepare('SELECT COUNT(*) FROM documents WHERE created_at >= DATE_SUB(CURDATE(), INTERVAL 7 DAY) AND uploaded_by=?');$s->execute([$uid]);return $s->fetchColumn();})());
$month = (int)($isAdmin ? $pdo->query('SELECT COUNT(*) FROM documents WHERE YEAR(created_at)=YEAR(CURDATE()) AND MONTH(created_at)=MONTH(CURDATE())')->fetchColumn() : (function() use($pdo,$uid){$s=$pdo->prepare('SELECT COUNT(*) FROM documents WHERE YEAR(created_at)=YEAR(CURDATE()) AND MONTH(created_at)=MONTH(CURDATE()) AND uploaded_by=?');$s->execute([$uid]);return $s->fetchColumn();})());
$year = (int)($isAdmin ? $pdo->query('SELECT COUNT(*) FROM documents WHERE YEAR(created_at)=YEAR(CURDATE())')->fetchColumn() : (function() use($pdo,$uid){$s=$pdo->prepare('SELECT COUNT(*) FROM documents WHERE YEAR(created_at)=YEAR(CURDATE()) AND uploaded_by=?');$s->execute([$uid]);return $s->fetchColumn();})());
$counts = $isAdmin ? $pdo->query('SELECT document_type, COUNT(*) total FROM documents GROUP BY document_type')->fetchAll() : (function() use($pdo,$uid){$s=$pdo->prepare('SELECT document_type,COUNT(*) total FROM documents WHERE uploaded_by=? GROUP BY document_type');$s->execute([$uid]);return $s->fetchAll();})();
$map = []; foreach ($counts as $c) $map[$c['document_type']] = (int)$c['total'];
$recent = $isAdmin ? $pdo->query('SELECT id,full_name,mobile,document_type,ref_no,created_at FROM documents ORDER BY id DESC LIMIT 6')->fetchAll() : (function() use($pdo,$uid){$s=$pdo->prepare('SELECT id,full_name,mobile,document_type,ref_no,created_at FROM documents WHERE uploaded_by=? ORDER BY id DESC LIMIT 6');$s->execute([$uid]);return $s->fetchAll();})();
require __DIR__ . '/header.php';
?>
<div class="welcome"><div><div class="eyebrow light">KU SOO DHAWOOW NIDAAMKA</div><h1>Maamul dukumentiyadaada si fudud.</h1><p>Kaydi, raadi, oo la soco warbixinnada dukumentiyada iyo xaadirinta shaqaalaha.</p><a class="btn white" href="document_new.php">＋ Xaree document cusub</a></div><div class="welcome-icon">▤</div></div>
<div class="stats-grid"><div class="stat-card"><div class="stat-icon purple">▤</div><span>Wadarta documents</span><strong><?=$total?></strong><small>Dhammaan dukumentiyada</small></div><div class="stat-card"><div class="stat-icon blue">◷</div><span>Maanta</span><strong><?=$today?></strong><small>La xareeyey maanta</small></div><div class="stat-card"><div class="stat-icon green">▥</div><span>Weekly report</span><strong><?=$week?></strong><small>7-dii maalmood ee u dambeeyey</small></div><div class="stat-card"><div class="stat-icon orange">▦</div><span>Monthly report</span><strong><?=$month?></strong><small>Bisha hadda</small></div><div class="stat-card"><div class="stat-icon pink">◫</div><span>Yearly report</span><strong><?=$year?></strong><small>Sannadka hadda</small></div></div>
<div class="section-heading"><div><h3>Noocyada dukumentiyada</h3><p>Tirada document kasta oo nidaamka ku jirta</p></div><a class="text-link" href="documents.php">Dhammaan documents →</a></div>
<div class="category-grid"><?php foreach (categories() as $i=>$cat): ?><a class="category-card" href="documents.php?type=<?=urlencode($cat)?>"><span class="category-icon c<?=$i?>"><?=['⌂','♧','🚘','✉','▣','⇄','▤','♧','⌂','§','🛡','🏡'][$i]?></span><span><?=e($cat)?></span><strong><?=$map[$cat] ?? 0?></strong><small>documents</small></a><?php endforeach; ?></div>
<div class="section-heading"><div><h3>Dukumentiyadii ugu dambeeyey</h3><p>Xogtii dhowaan la xareeyey</p></div><a class="text-link" href="document_new.php">+ Ku dar document</a></div>
<div class="table-wrap"><table><thead><tr><th>REF.No.</th><th>Magaca qofka</th><th>Mobile</th><th>Nooca documentiga</th><th>Taariikh</th></tr></thead><tbody><?php if (!$recent): ?><tr><td colspan="5" class="empty">Weli document lama xareyn.</td></tr><?php endif; ?><?php foreach($recent as $r): ?><tr><td><strong><?=e($r['ref_no'])?></strong></td><td><?=e($r['full_name'])?></td><td><?=e($r['mobile'])?></td><td><span class="pill"><?=e($r['document_type'])?></span></td><td><?=e(date('d/m/Y',strtotime($r['created_at'])))?></td></tr><?php endforeach; ?></tbody></table></div>
